import 'package:flutter/foundation.dart';

import 'geo_coordinate.dart';

/// Location source provider that produced a [GeoPosition].
enum GeoProvider {
  /// Hardware Global Navigation Satellite System (GPS / GLONASS / Galileo).
  gps,

  /// Multi-sensor fused provider combining GNSS, Wi-Fi, and inertial sensors.
  fused,

  /// Network-based provider (Wi-Fi / cellular triangulation).
  network,

  /// Wi-Fi positioning system.
  wifi,

  /// Cellular tower positioning.
  cell,

  /// Passive listener receiving fixes generated by other apps.
  passive,

  /// W3C Browser Geolocation API on Flutter Web.
  web,

  /// Built-in deterministic simulator for testing and previews.
  simulated,

  /// Unknown or platform-unspecified provider.
  unknown;

  /// Parses a provider identifier string returned by native platforms.
  static GeoProvider fromName(String? name) {
    if (name == null || name.isEmpty) return GeoProvider.unknown;
    switch (name.toLowerCase()) {
      case 'gps':
      case 'gnss':
      case 'satellite':
        return GeoProvider.gps;
      case 'fused':
      case 'corelocation':
      case 'winrt':
      case 'geoclue':
        return GeoProvider.fused;
      case 'network':
        return GeoProvider.network;
      case 'wifi':
        return GeoProvider.wifi;
      case 'cell':
      case 'cellular':
        return GeoProvider.cell;
      case 'passive':
        return GeoProvider.passive;
      case 'web':
      case 'browser':
        return GeoProvider.web;
      case 'simulated':
      case 'mock':
        return GeoProvider.simulated;
      default:
        return GeoProvider.unknown;
    }
  }
}

/// Signal quality classification derived from horizontal accuracy in meters.
enum GeoSignalQuality {
  /// Horizontal accuracy <= 10 meters (high-precision GNSS lock).
  excellent('Excellent', 4),

  /// Horizontal accuracy <= 25 meters.
  good('Good', 3),

  /// Horizontal accuracy <= 60 meters.
  fair('Fair', 2),

  /// Horizontal accuracy <= 150 meters.
  poor('Poor', 1),

  /// Horizontal accuracy > 150 meters or unavailable.
  weak('Weak', 0);

  const GeoSignalQuality(this.label, this.bars);

  /// Human-readable quality label.
  final String label;

  /// Discrete signal strength indicator from `0` (weak) to `4` (excellent).
  final int bars;

  /// Classifies a horizontal [accuracyMeters] radius into a [GeoSignalQuality].
  static GeoSignalQuality fromAccuracy(double accuracyMeters) {
    if (!accuracyMeters.isFinite || accuracyMeters < 0) {
      return GeoSignalQuality.weak;
    }
    if (accuracyMeters <= 10.0) return GeoSignalQuality.excellent;
    if (accuracyMeters <= 25.0) return GeoSignalQuality.good;
    if (accuracyMeters <= 60.0) return GeoSignalQuality.fair;
    if (accuracyMeters <= 150.0) return GeoSignalQuality.poor;
    return GeoSignalQuality.weak;
  }
}

/// An immutable, detailed geographic position fix reported by a platform
/// location provider.
@immutable
class GeoPosition {
  /// Creates a [GeoPosition].
  const GeoPosition({
    required this.coordinate,
    required this.timestamp,
    this.accuracy = 0.0,
    this.altitude = 0.0,
    this.altitudeAccuracy = 0.0,
    this.heading = 0.0,
    this.headingAccuracy = 0.0,
    this.speed = 0.0,
    this.speedAccuracy = 0.0,
    this.floor,
    this.isMocked = false,
    this.provider = GeoProvider.unknown,
  });

  /// Creates a [GeoPosition] directly from [latitude] and [longitude] values.
  factory GeoPosition.fromLatLng({
    required double latitude,
    required double longitude,
    DateTime? timestamp,
    double accuracy = 0.0,
    double altitude = 0.0,
    double altitudeAccuracy = 0.0,
    double heading = 0.0,
    double headingAccuracy = 0.0,
    double speed = 0.0,
    double speedAccuracy = 0.0,
    int? floor,
    bool isMocked = false,
    GeoProvider provider = GeoProvider.unknown,
  }) {
    return GeoPosition(
      coordinate: GeoCoordinate(latitude, longitude),
      timestamp: (timestamp ?? DateTime.now()).toUtc(),
      accuracy: accuracy.isFinite && accuracy >= 0 ? accuracy : 0.0,
      altitude: altitude.isFinite ? altitude : 0.0,
      altitudeAccuracy: altitudeAccuracy.isFinite && altitudeAccuracy >= 0
          ? altitudeAccuracy
          : 0.0,
      heading: heading.isFinite ? GeoMath.normalizeBearing(heading) : 0.0,
      headingAccuracy: headingAccuracy.isFinite && headingAccuracy >= 0
          ? headingAccuracy
          : 0.0,
      speed: speed.isFinite && speed >= 0 ? speed : 0.0,
      speedAccuracy: speedAccuracy.isFinite && speedAccuracy >= 0
          ? speedAccuracy
          : 0.0,
      floor: floor,
      isMocked: isMocked,
      provider: provider,
    );
  }

  /// Deserializes a [GeoPosition] from a platform channel or JSON map.
  factory GeoPosition.fromMap(Map<Object?, Object?> rawMap) {
    double readDouble(String key, [double fallback = 0.0]) {
      final v = rawMap[key];
      if (v is num && v.isFinite) return v.toDouble();
      return fallback;
    }

    final lat = readDouble('latitude');
    final lon = readDouble('longitude');
    final tsRaw = rawMap['timestamp'];
    DateTime timestamp;
    if (tsRaw is int) {
      timestamp = DateTime.fromMillisecondsSinceEpoch(tsRaw, isUtc: true);
    } else if (tsRaw is double && tsRaw.isFinite) {
      timestamp = DateTime.fromMillisecondsSinceEpoch(
        tsRaw.round(),
        isUtc: true,
      );
    } else if (tsRaw is String) {
      timestamp = DateTime.tryParse(tsRaw)?.toUtc() ?? DateTime.now().toUtc();
    } else {
      timestamp = DateTime.now().toUtc();
    }

    final floorRaw = rawMap['floor'];
    final floor = floorRaw is num ? floorRaw.toInt() : null;
    final mockedRaw = rawMap['isMocked'];
    final providerRaw = rawMap['provider'];

    return GeoPosition.fromLatLng(
      latitude: GeoMath.clampLatitude(lat),
      longitude: GeoMath.normalizeLongitude(lon),
      timestamp: timestamp,
      accuracy: readDouble('accuracy'),
      altitude: readDouble('altitude'),
      altitudeAccuracy: readDouble('altitudeAccuracy'),
      heading: readDouble('heading'),
      headingAccuracy: readDouble('headingAccuracy'),
      speed: readDouble('speed'),
      speedAccuracy: readDouble('speedAccuracy'),
      floor: floor,
      isMocked: mockedRaw is bool && mockedRaw,
      provider: GeoProvider.fromName(
        providerRaw is String ? providerRaw : null,
      ),
    );
  }

  /// WGS-84 coordinate of this fix.
  final GeoCoordinate coordinate;

  /// UTC timestamp when the position was recorded.
  final DateTime timestamp;

  /// Estimated horizontal accuracy radius in meters (`>= 0`).
  final double accuracy;

  /// Altitude in meters above the WGS-84 reference ellipsoid.
  final double altitude;

  /// Estimated vertical altitude accuracy in meters (`>= 0`).
  final double altitudeAccuracy;

  /// Direction of travel in degrees clockwise from true north `[0, 360)`.
  final double heading;

  /// Estimated heading accuracy in degrees (`>= 0`).
  final double headingAccuracy;

  /// Instantaneous ground speed in meters per second (`>= 0`).
  final double speed;

  /// Estimated speed accuracy in meters per second (`>= 0`).
  final double speedAccuracy;

  /// Building floor level when indoor positioning is available.
  final int? floor;

  /// Whether the operating system flagged this fix as coming from a mock
  /// location provider.
  final bool isMocked;

  /// Provider source that generated this position fix.
  final GeoProvider provider;

  /// Convenience getter for [GeoCoordinate.latitude].
  double get latitude => coordinate.latitude;

  /// Convenience getter for [GeoCoordinate.longitude].
  double get longitude => coordinate.longitude;

  /// Instantaneous speed converted to kilometers per hour (`km/h`).
  double get speedKmh => speed * 3.6;

  /// Instantaneous speed converted to statute miles per hour (`mph`).
  double get speedMph => speed * 2.2369362921;

  /// Instantaneous speed converted to knots (`kn`).
  double get speedKnots => speed * 1.9438444924;

  /// 16-point compass direction corresponding to [heading].
  CompassDirection get compassDirection =>
      CompassDirection.fromBearing(heading);

  /// Derived GNSS signal quality classification based on [accuracy].
  GeoSignalQuality get signalQuality => GeoSignalQuality.fromAccuracy(accuracy);

  /// Elapsed duration since [timestamp] relative to [now] (defaults to UTC now).
  Duration age({DateTime? now}) =>
      (now ?? DateTime.now().toUtc()).difference(timestamp);

  /// High-precision WGS-84 distance in meters from this fix to [other].
  double distanceTo(GeoPosition other) =>
      coordinate.distanceTo(other.coordinate);

  /// High-precision WGS-84 initial bearing in degrees from this fix to [other].
  double bearingTo(GeoPosition other) => coordinate.bearingTo(other.coordinate);

  /// Returns a copy of this [GeoPosition] with overridden fields.
  GeoPosition copyWith({
    GeoCoordinate? coordinate,
    DateTime? timestamp,
    double? accuracy,
    double? altitude,
    double? altitudeAccuracy,
    double? heading,
    double? headingAccuracy,
    double? speed,
    double? speedAccuracy,
    int? floor,
    bool? isMocked,
    GeoProvider? provider,
  }) {
    return GeoPosition(
      coordinate: coordinate ?? this.coordinate,
      timestamp: timestamp ?? this.timestamp,
      accuracy: accuracy ?? this.accuracy,
      altitude: altitude ?? this.altitude,
      altitudeAccuracy: altitudeAccuracy ?? this.altitudeAccuracy,
      heading: heading ?? this.heading,
      headingAccuracy: headingAccuracy ?? this.headingAccuracy,
      speed: speed ?? this.speed,
      speedAccuracy: speedAccuracy ?? this.speedAccuracy,
      floor: floor ?? this.floor,
      isMocked: isMocked ?? this.isMocked,
      provider: provider ?? this.provider,
    );
  }

  /// Serializes this [GeoPosition] into a JSON-compatible map.
  Map<String, Object?> toMap() => <String, Object?>{
    'latitude': latitude,
    'longitude': longitude,
    'timestamp': timestamp.millisecondsSinceEpoch,
    'accuracy': accuracy,
    'altitude': altitude,
    'altitudeAccuracy': altitudeAccuracy,
    'heading': heading,
    'headingAccuracy': headingAccuracy,
    'speed': speed,
    'speedAccuracy': speedAccuracy,
    if (floor != null) 'floor': floor,
    'isMocked': isMocked,
    'provider': provider.name,
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is GeoPosition &&
        other.coordinate == coordinate &&
        other.timestamp == timestamp &&
        other.accuracy == accuracy &&
        other.altitude == altitude &&
        other.altitudeAccuracy == altitudeAccuracy &&
        other.heading == heading &&
        other.headingAccuracy == headingAccuracy &&
        other.speed == speed &&
        other.speedAccuracy == speedAccuracy &&
        other.floor == floor &&
        other.isMocked == isMocked &&
        other.provider == provider;
  }

  @override
  int get hashCode => Object.hash(
    coordinate,
    timestamp,
    accuracy,
    altitude,
    altitudeAccuracy,
    heading,
    headingAccuracy,
    speed,
    speedAccuracy,
    floor,
    isMocked,
    provider,
  );

  @override
  String toString() =>
      'GeoPosition(${latitude.toStringAsFixed(6)}, ${longitude.toStringAsFixed(6)}, '
      '±${accuracy.toStringAsFixed(1)}m, ${speedKmh.toStringAsFixed(1)} km/h, '
      '${heading.toStringAsFixed(0)}° ${compassDirection.abbreviation})';
}
